/**
 * TIF-274 prerequisite, round 2 (D3): workbooks written by mainstream writers read, and
 * decide exactly as the CSV path and the independent grader do.
 *
 * The files in `test/fixtures/calc-xlsx-writers/` are real output, not hand-built XML:
 * LibreOffice Calc 24.2 (the live VM's app: Calc's CSV import then its xlsx export, and
 * Calc re-saving our generator's workbook) and openpyxl 3.1.5 (which declares `xmlns:r` on
 * each `<sheet>`, the case round 1 refused as XLSX_NOT_WORKBOOK). They are regenerated by
 * `scripts/calc-xlsx-writer-fixtures.ts`; the manifest pins each file's SHA-256 so a test run
 * always reads the bytes those writers produced.
 */
import { createHash } from "node:crypto";
import { describe, expect, it } from "vitest";
import { grade, sha256 } from "../../src/benchmark/grade/grade.ts";
import { buildRegistry, createGate, fileEvidenceReader } from "../../src/gate/gate.ts";
import { readXlsxDocument, readZipEntries } from "../../src/gate/xlsx-document.ts";
import { generateFixture } from "../../src/tasks/fixture.ts";
import { COLUMN_TYPES, INTENT, SEED } from "./calc-probes.ts";
import { tempRoot, writeState } from "./helpers.ts";
import { WRITERS_MANIFEST, writerBytes } from "./xlsx-writer-files.ts";

/**
 * What each committed workbook must get from the gate, and what the grader says.
 *
 * openpyxl's files are outside the byte grammar LibreOffice writes (single-quoted XML
 * declarations, other root namespace declarations), so since the raw-byte pre-scan they are
 * refused (`uncertain`, never verified), whatever the grader says (lead ruling 11:39Z).
 */
const OPENPYXL_REFUSED = {
  verdict: "uncertain",
  codes: ["STATE_CORRUPT"],
  reason: "could not look: persisted document is not a readable xlsx document (XLSX_PRESCAN_DECL)",
} as const;
const EXPECTED: Record<
  string,
  {
    verdict: "verified" | "refuted" | "uncertain";
    codes?: readonly string[];
    reason?: string;
    grader: "pass" | "fail";
  }
> = {
  "exact.lo.xlsx": { verdict: "verified", grader: "pass" },
  "roundtrip-exact.lo.xlsx": { verdict: "verified", grader: "pass" },
  "exact.openpyxl.xlsx": { ...OPENPYXL_REFUSED, grader: "pass" },
  "exact-text.openpyxl.xlsx": { ...OPENPYXL_REFUSED, grader: "pass" },
  "pristine.lo.xlsx": {
    verdict: "refuted",
    codes: ["ORACLE_FAIL", "TARGET_MISMATCH"],
    grader: "fail",
  },
  "pristine.openpyxl.xlsx": { ...OPENPYXL_REFUSED, grader: "fail" },
  "collateral.lo.xlsx": {
    verdict: "refuted",
    codes: ["ORACLE_FAIL", "DOCUMENT_COLLATERAL"],
    grader: "fail",
  },
  "collateral.openpyxl.xlsx": { ...OPENPYXL_REFUSED, grader: "fail" },
};

async function gateResult(bytes: Uint8Array) {
  const root = tempRoot();
  writeState(root, "r", "sheet.xlsx", bytes);
  return createGate({
    tasks: buildRegistry([
      {
        id: "w",
        family: "calc-record-edit",
        stateFile: "sheet.xlsx",
        spec: { fixtureSeed: SEED, ...INTENT, persistedFormat: "xlsx" },
      },
    ]),
    reader: fileEvidenceReader(root),
    assignment: { taskId: "w", runId: "r" },
  }).check({ taskId: "w", runId: "r" });
}

function graderStatus(bytes: Uint8Array) {
  const fixtureCsv = Buffer.from(generateFixture(SEED).csv);
  return grade({
    fixtureCsv,
    fixtureSha256: sha256(fixtureCsv),
    persisted: { format: "xlsx", bytes },
    intent: INTENT,
    columnTypes: COLUMN_TYPES,
  }).status;
}

describe("workbooks from LibreOffice Calc and openpyxl (round 2, D3)", () => {
  it("the manifest is the probe seed and edit, and names every expected workbook", () => {
    expect(WRITERS_MANIFEST.seed).toBe(SEED);
    expect(WRITERS_MANIFEST.edit).toEqual(INTENT);
    expect(WRITERS_MANIFEST.soffice).toMatch(/^LibreOffice 24\./);
    expect(WRITERS_MANIFEST.openpyxl).toBe("3.1.5");
    expect(Object.keys(WRITERS_MANIFEST.files).sort()).toEqual(Object.keys(EXPECTED).sort());
  });

  it.each(Object.keys(EXPECTED))("%s: bytes match the manifest", (name) => {
    const digest = createHash("sha256").update(writerBytes(name)).digest("hex");
    expect(digest).toBe(WRITERS_MANIFEST.files[name]?.sha256);
  });

  it("openpyxl declares xmlns:r on <sheet>, not on the workbook root (the round-1 refusal)", () => {
    const workbook = new TextDecoder().decode(
      readZipEntries(writerBytes("exact.openpyxl.xlsx")).get("xl/workbook.xml"),
    );
    expect(workbook).toMatch(/<workbook xmlns="[^"]+">/);
    expect(workbook).toContain(
      '<sheet xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"',
    );
    const lo = new TextDecoder().decode(
      readZipEntries(writerBytes("exact.lo.xlsx")).get("xl/workbook.xml"),
    );
    expect(lo).toMatch(/<workbook xmlns="[^"]+" xmlns:r="[^"]+">/);
  });

  it.each(Object.entries(EXPECTED))(
    "%s: the gate decides as expected, the grader agrees",
    async (name, want) => {
      const bytes = writerBytes(name);
      const result = await gateResult(bytes);
      expect(result.verdict).toBe(want.verdict);
      if (want.codes) expect(result.reasonCodes).toEqual(want.codes);
      if (want.reason) expect(result.reasons).toEqual([want.reason]);
      // The independent grader: it passes every verified one, and never fails a verified one.
      expect(graderStatus(bytes)).toBe(want.grader);
      if (want.verdict === "verified") expect(want.grader).toBe("pass");
      if (want.verdict === "refuted") expect(want.grader).toBe("fail");
    },
  );

  it("both LibreOffice exact workbooks read to the same cells", () => {
    const lo = readXlsxDocument(writerBytes("exact.lo.xlsx")).cells;
    expect(readXlsxDocument(writerBytes("roundtrip-exact.lo.xlsx")).cells).toEqual(lo);
  });
});
